// EDIT THESE VALUES ONCE. Everything downstream reads from here.
const CONFIG = {
  calendarId: 'primary',                    // Google Calendar ID, "primary" or an email address
  timezone: 'Asia/Kolkata',                 // IANA timezone used for parsing and display
  businessName: 'Your Company',
  senderName: 'Scheduling Team',
  fromEmail: 'user@example.com',  // must be allowed by your SMTP account
  supportEmail: 'user@example.com',
  logSheetId: 'PASTE_GOOGLE_SHEET_ID_HERE',
};

const f = $input.item.json;
const pick = (k) => (f[k] === undefined || f[k] === null ? '' : String(f[k]).trim());

return {
  json: {
    ...CONFIG,
    action: pick('Action').toLowerCase(),
    email: pick('Email').toLowerCase(),
    eventId: pick('Meeting ID'),
    newDate: pick('New Date'),
    newTime: pick('New Time'),
    submittedAt: f.submittedAt || new Date().toISOString(),
  },
};

const ev = $input.item.json;
const req = $('Prepare Request').item.json;
const tz = req.timezone;

const start = (ev.start && (ev.start.dateTime || ev.start.date)) || '';
const end = (ev.end && (ev.end.dateTime || ev.end.date)) || '';
const attendee = (ev.attendees || []).find(a => (a.email || '').toLowerCase() === req.email) || {};
const meetLink = ev.hangoutLink
  || (ev.conferenceData && ev.conferenceData.entryPoints && ev.conferenceData.entryPoints[0] && ev.conferenceData.entryPoints[0].uri)
  || ev.htmlLink || '';

const fmt = 'cccc, dd LLL yyyy, hh:mm a';
const label = ev.start && ev.start.dateTime
  ? DateTime.fromISO(ev.start.dateTime).setZone(tz).toFormat(fmt) + ' (' + tz + ')'
  : start;

return {
  json: {
    ...req,
    eventId: ev.id,
    meetingTitle: ev.summary || 'Meeting',
    meetingStart: start,
    meetingEnd: end,
    meetingStartLabel: label,
    meetingLink: meetLink,
    attendeeName: attendee.displayName || req.email.split('@')[0],
    hostEmail: (ev.organizer && ev.organizer.email) || '',
  },
};

// Parses the requested new time and returns ISO start/end in the configured timezone.
// Accepted New Time formats:
//   "06:00 PM - 07:00 PM"        (range, with "-", "to" or an en dash)
//   "6:00 PM"                    (start only, keeps original duration)
//   "18:00-19:00"                (24 hour)
//   "2025-07-01T18:00:00+05:30"  (full ISO start, keeps original duration)
// newDate is optional (YYYY-MM-DD). Falls back to the original meeting date, then today.

const item = $input.item.json;
const tz = item.timezone || 'Asia/Kolkata';
const raw = (item.newTime || '').toString().trim();
const dateStr = (item.newDate || '').toString().trim();

const origStart = item.meetingStart ? DateTime.fromISO(item.meetingStart, { zone: tz }) : null;
const origEnd = item.meetingEnd ? DateTime.fromISO(item.meetingEnd, { zone: tz }) : null;
let durationMin = 30;
if (origStart && origEnd && origStart.isValid && origEnd.isValid) {
  durationMin = Math.max(5, Math.round(origEnd.diff(origStart, 'minutes').minutes));
}

let baseDate = DateTime.now().setZone(tz);
if (/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
  baseDate = DateTime.fromISO(dateStr, { zone: tz });
} else if (origStart && origStart.isValid) {
  baseDate = origStart;
}

const timeFormats = ['hh:mm a', 'h:mm a', 'hh a', 'h a', 'HH:mm', 'H:mm', 'hh:mma', 'h:mma'];
function parseClock(text) {
  const clean = text.trim().replace(/\s+/g, ' ').toUpperCase();
  for (const f of timeFormats) {
    const t = DateTime.fromFormat(clean, f, { zone: tz });
    if (t.isValid) {
      return baseDate.set({ hour: t.hour, minute: t.minute, second: 0, millisecond: 0 });
    }
  }
  return null;
}

let start = null;
let end = null;
let error = '';

if (!raw) {
  error = 'New time is missing';
} else {
  const iso = DateTime.fromISO(raw, { zone: tz });
  if (iso.isValid && /\d{4}-\d{2}-\d{2}T/.test(raw)) {
    start = iso;
    end = start.plus({ minutes: durationMin });
  } else {
    const parts = raw.split(/\s*(?:-|\u2013|\u2014|to)\s*/i).filter(Boolean);
    start = parseClock(parts[0] || '');
    if (!start) {
      error = 'Could not understand the time "' + raw + '"';
    } else if (parts.length > 1) {
      end = parseClock(parts[1]);
      if (!end) error = 'Could not understand the end time "' + parts[1] + '"';
      else if (end <= start) end = end.plus({ days: 1 });
    } else {
      end = start.plus({ minutes: durationMin });
    }
  }
}

if (!error && start && start < DateTime.now().setZone(tz)) {
  error = 'The requested time is in the past';
}

const fmt = "cccc, dd LLL yyyy, hh:mm a";
return {
  json: {
    ...item,
    parseError: error,
    newStart: !error && start ? start.toISO() : '',
    newEnd: !error && end ? end.toISO() : '',
    newStartLabel: !error && start ? start.toFormat(fmt) + ' (' + tz + ')' : '',
    newEndLabel: !error && end ? end.toFormat('hh:mm a') : '',
  },
};
